<script setup lang="ts">
import { computed, watch } from 'vue';
import { router, Link } from '@inertiajs/vue3';
import { route } from 'ziggy-js';
import { FileText } from '@lucide/vue';
import AppLayout from '../../Layouts/AppLayout.vue';
import { searchState } from '../../composables/search';
defineOptions({ layout: AppLayout });
const props=defineProps<{tests:{data:Array<any>;current_page:number;last_page:number;from:number;to:number;total:number;per_page:number};filters:{status?:string;search?:string}}>(); searchState.value=props.filters?.search??''; const currentPage=computed(()=>props.tests.current_page); const performSearch=(search:string)=>router.get(route('tests.index'),{search:search||undefined,per_page:props.tests.per_page},{preserveState:true,preserveScroll:true}); watch(searchState,(val)=>performSearch(val)); const onPageChange=(page:number)=>router.get(route('tests.index'),{page,per_page:props.tests.per_page,search:searchState.value||undefined,status:props.filters.status},{preserveScroll:true,preserveState:true}); const statusClass=(status:string)=>({OK:'bg-emerald-100 text-emerald-700',NG:'bg-red-100 text-red-700',SPARE:'bg-blue-100 text-blue-700',SERVICE:'bg-amber-100 text-amber-700'}[status]??'bg-slate-100 text-slate-600');
</script>
<template><div class="mx-auto max-w-5xl"><div v-if="tests.data.length===0" class="flex flex-col items-center justify-center rounded-xl border border-dashed border-slate-300 bg-white p-12 text-slate-400"><FileText :size="48" /><p class="mt-3 text-sm">Tidak ada data pengujian.</p></div><div v-else class="space-y-3"><Link v-for="t in tests.data" :key="t.id" :href="route('tests.show',{test:t.id})" class="block rounded-xl border border-slate-200 bg-white p-4 shadow-sm transition hover:border-orange-200 hover:shadow-md"><div class="flex items-center justify-between gap-3"><span class="font-mono text-sm font-bold">{{ t.instrument?.code }}</span><span class="rounded-full px-2 py-1 text-[10px] font-bold" :class="statusClass(t.status)">{{ t.status }}</span></div><div class="mt-2 flex flex-wrap gap-x-4 gap-y-1 text-xs text-slate-500"><span>{{ t.instrument?.type?.name }}</span><span>{{ t.test_date }}</span><span>Next: {{ t.next_test_date }}</span><span>{{ t.tester?.name }}</span></div></Link></div><div v-if="tests.last_page>1" class="mt-6 flex items-center justify-center gap-3"><button class="page-button" :disabled="currentPage<=1" @click="onPageChange(currentPage-1)">Sebelumnya</button><span class="text-sm text-slate-500">{{ currentPage }} / {{ tests.last_page }}</span><button class="page-button" :disabled="currentPage>=tests.last_page" @click="onPageChange(currentPage+1)">Selanjutnya</button></div></div></template>
<style scoped>.page-button{border:1px solid #e2e8f0;border-radius:.625rem;background:#fff;padding:.55rem .8rem;font-size:.75rem;font-weight:600;color:#c2410c}.page-button:disabled{cursor:not-allowed;opacity:.4}</style>
